const milestones={5:{title:'The Font Below',text:'A silver font wells up from the cracked stone. Something beneath the water whispers your childhood name.',choices:[['Drink from the font','Gain a lasting vitality boon: +20% damage this run.','font'],['Bottle the water','Take 80 gold; the water remembers your touch.','bottle'],['Turn away','The voice follows. Gain 12 Soul Shards.','refuse']]},10:{title:'The Bell That Sank',text:'A bell hangs in the cathedral nave, tolling without a clapper. Its note arrives a heartbeat before it sounds.',choices:[['Shatter the bell','The echo wounds every foe: +35% damage this run.','shatter'],['Record the strange runes','The Codex opens a sealed memory. Gain 18 shards.','record'],['Listen until dawn','A spectral guide marks your path: +25% gold.','listen']]},20:{title:'The Cartographer’s Last Map',text:'A drowned cartographer’s map redraws itself in your hands. Every road points toward the same black star.',choices:[['Follow the black star','Learn a hidden route. Gain 35 shards and +20% damage.','star'],['Sell the map to a shade','Gain 250 gold; the shade knows your face.','sell'],['Burn the map','Its ashes grant +50% gold this run.','burn']]},30:{title:'The Sunken Crown',text:'At the citadel’s heart, a crown rests upon a throne of salt. A voice—your own, older and colder—says: “Again?”',choices:[['Wear the crown','Claim +50 shards and +30% damage.','crown'],['Leave it for another self','Unlock the Crownless chapter. Gain 30 shards.','leave'],['Ask who is speaking','The voice remembers your past lives.','ask']]}};
const effect=key=>{let out={damage:s.boons.ember?1.25:1,gold:1,shard:1,crit:.05,spell:1};for(const b of branches) b.nodes.forEach((node,i)=>{if(s.skills.includes(b.name+':'+i)) Object.entries(node[3]).forEach(([k,v])=>{if(k==='damage'||k==='gold'||k==='shard'||k==='spell')out[k]*=v;else if(k==='crit')out[k]+=v})});if(s.runFlags.includes('font'))out.damage*=1.2;if(s.runFlags.includes('shatter'))out.damage*=1.35;if(s.runFlags.includes('star'))out.damage*=1.2;if(s.runFlags.includes('crown'))out.damage*=1.3;if(s.runFlags.includes('listen'))out.gold*=1.25;if(s.runFlags.includes('burn'))out.gold*=1.5;return out};
function log(msg){const el=$('combat-log');el.innerHTML='<div>› '+msg+'</div>'+el.innerHTML;while(el.children.length>8)el.lastChild.remove()}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function save(){s.lastSave=Date.now();try{localStorage.setItem(KEY,JSON.stringify(s))}catch(e){toast('Local save unavailable')}}
function showModal(html){$('modal-content').innerHTML=html;$('modal-back').classList.remove('hidden')}
function closeModal(){$('modal-back').classList.add('hidden')}
function audio(type){if(s.muted)return;try{ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();let now=ctx.currentTime,notes=type==='prestige'?[220,330,440,660]:type==='crit'?[580,880,1170]:type==='coin'?[700,980]:type==='skill'?[390,520,780]:type==='spell'?[180,420,820]:[180,110];notes.forEach((f,i)=>{let o=ctx.createOscillator(),g=ctx.createGain();o.type=type==='hit'?'square':'triangle';o.frequency.setValueAtTime(f,now+i*.045);o.frequency.exponentialRampToValueAtTime(Math.max(60,f*.65),now+i*.045+.12);g.gain.setValueAtTime(.055,now+i*.045);g.gain.exponentialRampToValueAtTime(.001,now+i*.045+.15);o.connect(g);g.connect(ctx.destination);o.start(now+i*.045);o.stop(now+i*.045+.16)})}catch(e){}}
function statMultipliers(){let e=effect('');return{damage:e.damage,gold:e.gold,shard:e.shard,crit:e.crit,spell:e.spell}}
function saveAndRender(){save();render()}
function offline(seconds){seconds=clamp(seconds,0,12*3600);if(seconds<3)return;let rate=Math.max(1,s.floor*.48)*(1+s.ascensions*.18)*effect('').gold;let gold=Math.floor(seconds/60*rate),shards=Math.floor(seconds/600*(1+s.ascensions*.08)*effect('').shard);s.gold+=gold;s.shards+=shards;s.lastSave=Date.now();save();render();if(gold||shards)showModal(`<h2>Welcome back, delver.</h2><p>The citadel kept turning while you were away. Your local clock records <b>${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m</b> in the dark.</p><div class="card"><div class="statrow"><span>Gold recovered</span><b>+${fmt(gold)}</b></div><div class="statrow"><span>Soul Shards gathered</span><b>+${fmt(shards)} ◈</b></div></div><p class="smallmuted">Offline gains are estimated from your current depth and capped at 12 hours.</p><button class="btn gold" id="modal-close" style="width:100%">RETURN TO THE WARRens</button>`);$('modal-close').onclick=closeModal}

