input.newString:
function offline(seconds){seconds=clamp(seconds,0,12*3600);if(seconds<3)return;let rate=Math.max(1,s.floor*.48)*(1+s.ascensions*.18)*effect('').gold*(s.boons.fate?1.5:1);let gold=Math.floor(seconds/60*rate),shards=Math.floor(seconds/600*(1+s.ascensions*.08)*effect('').shard);s.gold+=gold;s.shards+=shards;s.lastSave=Date.now();save();render();if(gold||shards)showModal(`<h2>Welcome back, delver.</h2><p>The citadel kept turning while you were away. Your local clock records <b>${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m</b> in the dark.</p><div class="card"><div class="statrow"><span>Gold recovered</span><b>+${fmt(gold)}</b></div><div class="statrow"><span>Soul Shards gathered</span><b>+${fmt(shards)} ◈</b></div></div><p class="smallmuted">Offline gains are estimated from your current depth and capped at 12 hours.</p><button class="btn gold" id="modal-close" style="width:100%">RETURN TO THE WARRENS</button>`);$('modal-close').onclick=closeModal}
function startEnemy(){enemyMax=Math.ceil(10*Math.pow(1.19,s.floor-1)*(s.floor%10===0?5:1));enemyHP=enemyMax;let names=['ASHEN WRETCH','DROWNED ACOLYTE','GLOAM HOUND','SALT-BONE KNIGHT','HOLLOW LANTERN'];let boss=s.floor%10===0;$('enemy-name').textContent=boss?['THE BELL-KEEPER','MOTHER OF SALT','THE CROWNLESS'][((s.floor/10)-1)%3]:names[Math.floor(Math.random()*names.length)];$('enemy-type').textContent=boss?'CITADEL BOSS':'WANDERING';$('scene').classList.toggle('boss',boss);$('enemy-hpbar').style.width='100%';$('foe-count').textContent=s.foe+1}
function hit(amount,kind='hit'){if($('modal-back').classList.contains('hidden')===false)return;let critical=Math.random()<effect('').crit;if(critical)amount*=2;enemyHP-=amount;audio(critical?'crit':kind);if(enemyHP<=0)defeat();else{$('enemy-hpbar').style.width=(enemyHP/enemyMax*100)+'%';if(Math.random()<.14)log(critical?'A critical blow rends the dark!':'Your strike finds its mark.')}}
function defeat(){let boss=s.floor%10===0;let m=effect(''),gold=Math.ceil((7+s.floor*2)*(boss?8:1)*m.gold),shard=Math.ceil((1+(boss?8:0))*m.shard);s.gold+=gold;s.shards+=shard;s.totalKills++;audio('coin');log(`${boss?'BOSS FALLEN':'Foe defeated'} · +${gold} gold, +${shard} shards`);s.foe++;if(s.foe>=10){s.foe=0;s.floor++;s.best=Math.max(s.best,s.floor);log(`Floor ${s.floor} reached. The air grows colder.`);if(milestones[s.floor]&&!s.storySeen.includes(s.floor)){s.storySeen.push(s.floor);s.lastSave=Date.now();save();render();showStory(s.floor);return}}startEnemy();render();save()}
function showStory(floor){const event=milestones[floor];if(!event)return;showModal(`<div class="eyebrow">A MEMORY STIRS · FLOOR ${floor}</div><h2>${event.title}</h2><p>${event.text}</p>${s.ascensions?`<p style="color:#c59bea">The voice recognizes your ${s.ascensions} previous ${s.ascensions===1?'descent':'descents'}. “You have been here before.”</p>`:''}${event.choices.map(([label,desc,key])=>`<button class="choice" data-choice="${key}"><b>${label}</b><br>${desc}</button>`).join('')}`);document.querySelectorAll('[data-choice]').forEach(btn=>btn.onclick=()=>chooseStory(floor,btn.dataset.choice))}
function chooseStory(floor,key){let event=milestones[floor],choice=event.choices.find(c=>c[2]===key);if(!choice)return;s.choices[floor]=key;s.runFlags.push(key);let rewards={bottle:()=>s.gold+=80,refuse:()=>s.shards+=12,record:()=>s.shards+=18,sell:()=>s.gold+=250,star:()=>s.shards+=35,crown:()=>s.shards+=50,leave:()=>s.shards+=30};if(rewards[key])rewards[key]();if(key==='ask'&&s.ascensions>=2)s.codex.push({title:'The Voice in the Salt',text:'After two ascensions, the voice admits it is not a god. It is the shape your soul leaves in the water.'});if(key==='leave')s.codex.push({title:'The Crownless Chapter',text:'You left the crown for the self who comes after. The throne stood empty, waiting.'});if((key==='record'||key==='star'||key==='ask')&&!s.codex.some(c=>c.title===event.title))s.codex.push({title:event.title,text:choice[1]+' The citadel has recorded this choice.'});closeModal();audio('skill');log(`Memory altered: ${choice[0]}.`);saveAndRender()}

